    drawProps(world.city);
    drawTrafficLights(world.city, world.time);
    drawMarkers(world);
    for (const vehicle of world.vehicles) if (!vehicle.exploded) drawVehicle(vehicle);
    for (const ped of world.peds) drawPed(ped);
