      particle.x += particle.vx * step;
      particle.y += particle.vy * step;
      if (particle.kind === 'smoke') particle.size += 12 * step;
      if (particle.life <= 0) particles.splice(index, 1);
    }
    for (let index = shockwaves.length - 1; index >= 0; index -= 1) {
